(903000, 0, 0, 1, 101, 0, 1, -1, 3, 1, 0, 1, 0, 0, 1, 'Study the card', 'Étudier la carte', 255, 'Study this card: it joins the binder of every character of your account. The card is consumed.', 'Étudier cette carte : elle rejoint le classeur de tous les personnages de votre compte. La carte est consommée.', 255, '', '', 0, 1),
(903001, 0, 0, 1, 101, 0, 1, -1, 3, 1, 0, 1, 0, 0, 1, 'Study the board', 'Étudier le plateau', 255, 'Study this board: it joins the binder of every character of your account. The board is consumed.', 'Étudier ce plateau : il rejoint le classeur de tous les personnages de votre compte. Le plateau est consommé.', 255, '', '', 0, 1),
